14. tokenized_state_machine!{
15.     DistRwLock<T> {
16.         fields {
17.             #[sharding(constant)]
18.             pub rc_width: int,
19. 
20.             #[sharding(storage_option)]
21.             pub storage: Option<T>,
22. 
