39.             pub shared_guard: Multiset<(int, T)>,
40.         }
41. 
42.         init!{
43.             initialize(rc_width: int, init_t: T) {
44.                 require(0 < rc_width);
45.                 init rc_width = rc_width;
46.                 init storage = Option::Some(init_t);
47.                 init exc_locked = false;
48.                 init ref_counts = IMap::new(
49.                     |i| 0 <= i < rc_width,
50.                     |i| 0,
51.                 );
52.                 init exc_pending = Option::None;
53.                 init exc_guard = Option::None;
54.                 init shared_pending = Multiset::empty();
55.                 init shared_guard = Multiset::empty();
56.             }
57.         }
58. 
59.         transition!{
60.             exc_start() {
61.                 require(!pre.exc_locked);
62.                 update exc_locked = true;
63.                 add exc_pending += Some(0);
64.             }
65.         }
66. 
67.         transition!{
68.             exc_check_count() {
69.                 remove exc_pending -= Some(let r);
70.                 have ref_counts >= [r => 0];
71. 
72.                 add exc_pending += Some(r + 1);
73.             }
74.         }
75. 
76.         transition!{
77.             exc_finish() {
78.                 remove exc_pending -= Some(pre.rc_width);
79.                 add exc_guard += Some(());
80.                 withdraw storage -= Some(let _);
81.             }
82.         }
83. 
84.         transition!{
85.             exc_release(t: T) {
86.                 update exc_locked = false;
87.                 remove exc_guard -= Some(());
88.                 deposit storage += Some(t);
89.             }
90.         }
91. 
92.         transition!{
93.             shared_start(r: int) {
94.                 remove ref_counts -= [r => let rc];
95.                 add ref_counts += [r => rc + 1];
96.                 add shared_pending += {r};
97.             }
98.         }
99. 
100.         transition!{
101.             shared_finish(r: int) {
102.                 require(!pre.exc_locked);
103.                 remove shared_pending -= {r};
104. 
105.                 birds_eye let t = pre.storage->0;
106.                 add shared_guard += {(r, t)};
107.             }
108.         }
109. 
110.         transition!{
111.             shared_release(val: (int, T)) {
112.                 remove shared_guard -= {val};
113. 
114.                 let r = val.0;
115.                 remove ref_counts -= [r => let rc];
116.                 add ref_counts += [r => rc - 1];
117. 
118.                 assert(rc > 0) by {
119.                     assert(0 <= r < pre.rc_width);
120.                     assert(pre.shared_guard.count(val) > 0);
121.                     assert(Self::filter_r(pre.shared_guard, r).count(val) > 0);
122.                     assert(Self::filter_r(pre.shared_guard, r).len() > 0);
123.                     assert(pre.ref_counts.index(r) > 0);
124.                 };
125.             }
126.         }
127. 
128.         property!{
129.             do_guard(val: (int, T)) {
130.                 have shared_guard >= {val};
131.                 guard storage >= Some(val.1);
132.             }
133.         }
134. 
135. 
136.         #[invariant]
137.         pub fn ref_counts_domain(&self) -> bool {
138.             &&& 0 < self.rc_width
139.             &&& forall |i: int| 0 <= i < self.rc_width <==> self.ref_counts.dom().contains(i)
140.         }
141. 
142.         #[invariant]
143.         pub fn exc_inv(&self) -> bool {
144.             &&& self.exc_locked <==> (self.exc_pending is Some || self.exc_guard is Some)
145.             &&& self.storage is Some <==> self.exc_guard is None
146.             &&& if let Option::Some(cur_r) = self.exc_pending {
147.                 &&& 0 <= cur_r <= self.rc_width
148.                 &&& self.exc_guard is None
149.                 &&& forall |x| self.shared_guard.count(x) > 0 ==> !(0 <= x.0 < cur_r)
150.             } else {
151.                 true
152.             }
153.         }
154. 
155.         #[invariant]
156.         pub fn shared_pending_in_range(&self) -> bool {
157.             forall |r| self.shared_pending.count(r) > 0 ==> (0 <= r < self.rc_width)
158.         }
159. 
160.         #[invariant]
161.         pub fn shared_guard_in_range(&self) -> bool {
162.             forall |x| self.shared_guard.count(x) > 0 ==> (0 <= x.0 < self.rc_width)
163.         }
164. 
165.         #[invariant]
166.         pub fn shared_inv_agree(&self) -> bool {
167.             forall |v| #[trigger] self.shared_guard.count(v) > 0 ==>
168.                 self.storage == Option::Some(v.1)
169.         }
170. 
171.         pub closed spec fn filter_r(shared_guard: Multiset<(int, T)>, r: int) -> Multiset<(int, T)> {
172.             shared_guard.filter(|val: (int, T)| val.0 == r)
173.         }
174. 
175.         #[invariant]
176.         pub fn shared_counts_agree(&self) -> bool {
177.             forall |r| 0 <= r < self.rc_width ==>
178.                 #[trigger] self.ref_counts.index(r) ==
179.                     self.shared_pending.count(r) as int +
180.                         Self::filter_r(self.shared_guard, r).len() as int
181.         }
182. 
183.         #[inductive(initialize)]
184.         fn initialize_inductive(post: Self, rc_width: int, init_t: T) {
185.         }
186.         #[inductive(exc_start)]
187.         fn exc_start_inductive(pre: Self, post: Self) {
188.             admit()
189.         }
190.         #[inductive(exc_check_count)]
191.         fn exc_check_count_inductive(pre: Self, post: Self) {
192.             admit()
193.         }
194.         #[inductive(exc_finish)]
195.         fn exc_finish_inductive(pre: Self, post: Self) {
196.             admit()
197.         }
198.         #[inductive(exc_release)]
199.         fn exc_release_inductive(pre: Self, post: Self, t: T) {
200.             admit()
201.         }
202.         #[inductive(shared_start)]
203.         fn shared_start_inductive(pre: Self, post: Self, r: int) {
